const recordComparison = `-- name: RecordComparison :exec
INSERT INTO imports_root (root_id, place, compared_at, found, changed, gone, returned, added, stopped_gone, stopped_of)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (root_id) DO UPDATE SET
    place = excluded.place, compared_at = excluded.compared_at, found = excluded.found, changed = excluded.changed, gone = excluded.gone,
    returned = excluded.returned, added = excluded.added, stopped_gone = excluded.stopped_gone, stopped_of = excluded.stopped_of
`

type RecordComparisonParams struct {
	RootID      roots.ID
	Place       int64
	ComparedAt  storage.Time
	Found       int64
	Changed     int64
	Gone        int64
	Returned    int64
	Added       int64
	StoppedGone *int64
	StoppedOf   *int64
}

func (q *Queries) RecordComparison(ctx context.Context, arg RecordComparisonParams) error {
	_, err := q.db.ExecContext(ctx, recordComparison,
		arg.RootID,
		arg.Place,
		arg.ComparedAt,
		arg.Found,
		arg.Changed,
		arg.Gone,
		arg.Returned,
		arg.Added,
		arg.StoppedGone,
		arg.StoppedOf,
	)
	return err
}

const setFile = `-- name: SetFile :execrows
UPDATE imports_file SET outcome = ?1, reason = ?2, hold = ?3, confirmed = ?4,
                        probe = ?5, quality = ?6, cut = ?7, release_name = ?8,
                        root_id = ?9, dest = ?10, sent_transfer = ?11,
                        sent_order = ?12, placed_by = ?13, file_id = ?14,
                        source_removed_at = ?15
WHERE import_id = ?16 AND position = ?17 AND outcome = ?18
`

type SetFileParams struct {
	Outcome         string
	Reason          *string
	Hold            *string
	Confirmed       int64
	Probe           *media.Record
	Quality         *release.Quality
	Cut             release.CutKey
	ReleaseName     string
	RootID          roots.ID
	Dest            *string
	SentTransfer    transfers.ID
	SentOrder       *int64
	PlacedBy        *string
	FileID          files.ID
	SourceRemovedAt storage.Time
	ImportID        ImportID
	Position        int64
	Was             string
}

func (q *Queries) SetFile(ctx context.Context, arg SetFileParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setFile,
		arg.Outcome,
		arg.Reason,
		arg.Hold,
		arg.Confirmed,
		arg.Probe,
		arg.Quality,
		arg.Cut,
		arg.ReleaseName,
		arg.RootID,
		arg.Dest,
		arg.SentTransfer,
		arg.SentOrder,
		arg.PlacedBy,
		arg.FileID,
		arg.SourceRemovedAt,
		arg.ImportID,
		arg.Position,
		arg.Was,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

